"""Logo-derived decoration and practical editorial content for the shared site build."""


def brand_mark(cls=''):
    # Five faces traced from the supplied logo; keep their proportions and source colours.
    return f'''<svg class="brand-mark {cls}" data-brand-mark viewBox="0 0 445 445" aria-hidden="true" focusable="false"><polygon class="brand-face face-sand" fill="#bda78f" points="129,6 372,6 304,124 197,124"/><polygon class="brand-face face-taupe" fill="#837670" points="129,6 197,124 143,217 6,217"/><polygon class="brand-face face-copper" fill="#cb844c" points="6,217 143,217 197,311 129,430"/><polygon class="brand-face face-plum" fill="#302130" points="197,311 304,311 372,430 129,430"/><polygon class="brand-face face-red" fill="#a33939" points="250,217 385,217 439,313 372,430 304,311"/></svg>'''


def home_hero(button):
    return f'''<section class="hero hero-original"><div class="hero-backdrop"><picture><source media="(max-width:740px)" srcset="/assets/hero-original-mobile-480.webp 480w, /assets/hero-original-mobile-800.webp 800w" sizes="100vw"><img src="/assets/hero-original-1536.webp" srcset="/assets/hero-original-960.webp 960w, /assets/hero-original-1536.webp 1536w" sizes="100vw" width="1536" height="864" alt="Multicoloured block paved driveway with a contrasting edge in front of a stone house" loading="eager" fetchpriority="high" decoding="async"></picture></div><div class="hero-shade"></div><div class="hero-geometry">{brand_mark('large')}</div><div class="wrap hero-content"><span class="eyebrow">George Entwistle · Driveways & Paving</span><h1><span class="hero-line">Expert driveways &amp;</span><br><span class="hero-highlight">paving in Colne</span>,<br>Burnley &amp; Pendle</h1><p>Also proudly serving Barnoldswick, Skipton and the surrounding areas. High-quality tarmac, resin, block paving, patios and garden landscaping, with care in every detail.</p><div class="actions">{button('Request a free quote','#get-a-quote')}{button('View our portfolio','/gallery/','outline')}</div><div class="hero-bottom"><span>Based in Colne</span><span>Free site visits</span><span>No-obligation quotes</span></div></div><a class="hero-scroll" href="#services">Discover our services <span aria-hidden="true">↓</span></a></section>'''


def brand_divider():
    return f'<div class="brand-divider wrap" aria-hidden="true">{brand_mark()}</div>'


def service_guide(button, faq):
    choices = [
        ('01','A new entrance','If parking, turning or reaching the front door is awkward, start with the driveway layout. Compare tarmac, resin and block paving alongside the width, levels and drainage. A path or contrasting border can make the route to the door clearer.','/services/driveways/','Explore driveway options'),
        ('02','A place to sit outside','For dining or relaxing in the garden, think about furniture and the space around it before choosing slabs. Indian stone and porcelain offer different looks; the patio also needs to connect comfortably to doors, paths, steps and the lawn.','/services/patios/','Plan your patio'),
        ('03','A more useful garden','If several parts of the garden need changing, consider them together. Paving, lawns, planting, edging and fencing all affect the finished layout. Share the features you want to keep and the jobs that would make the biggest difference.','/services/landscaping/','Explore landscaping'),
    ]
    cards=''.join(f'<article class="material-card" data-reveal><span class="eyebrow">{number} · Where to start</span><h3>{title}</h3><p>{copy}</p><a class="text-link" href="{url}">{label} <span aria-hidden="true">↗</span></a></article>' for number,title,copy,url,label in choices)
    return f'''<section class="section white content-band"><div class="wrap"><div class="section-heading" data-reveal><div><span class="eyebrow">Choose the right starting point</span><h2>What do you want<br>your space to do?</h2></div><p>You do not need to arrive with a finished design. How you use the property is the best starting point.</p></div><div class="material-grid">{cards}</div></div></section><section class="section"><div class="wrap content-layout"><article><span class="eyebrow">Materials &amp; the finishing details</span><h2>A finish that fits the setting.</h2><p>For a driveway, the main choices include a continuous tarmac surface, resin-bound aggregate and individual paving blocks. Their colours, texture and detailing create different effects. The construction beneath the surface and the way water is managed also need to suit the actual site.</p><p>In the garden, natural stone brings variations in colour and markings, while porcelain can provide a more uniform finish. Slab size, laying pattern and joint colour influence the overall appearance. Look at several examples alongside the brickwork, stone and boundary features around your home.</p><h2>Plan adjoining work together.</h2><p>A new patio may also need a path, steps or a neater lawn edge. A driveway may meet a gate, garden wall or pedestrian entrance. Discuss those connections at the same time as the main surface so they are included in the agreed scope, rather than left as awkward gaps between separate jobs.</p><p>We also offer timber fencing and wider garden improvements. Tell George about the whole project, even if one part is your immediate priority. A free site visit lets us look at access, ground conditions and the work needed before providing a no-obligation quote.</p></article><aside class="service-aside"><span class="eyebrow">Your first conversation</span><h2>Bring your ideas.<br>We’ll look at the details.</h2><p>A postcode, a few photographs and a rough idea of size are useful. Tell us about any puddles, uneven areas or access restrictions too.</p>{button('Arrange a site visit')}</aside></div></section><section class="section white"><div class="wrap"><div class="section-heading" data-reveal><div><span class="eyebrow">Planning your project</span><h2>A few useful answers.</h2></div></div>{faq([{'q':'Can you help if I am unsure which material to choose?','a':'Yes. Explain the finish you like, how you will use the area and your priorities for upkeep. We can discuss suitable options during the site visit, with the ground and surroundings in view.'},{'q':'Can one quote cover a driveway, patio and fencing?','a':'Tell George about all the work you are considering. The visit helps establish which elements should be considered together and what the agreed quotation should include.'},{'q':'Do you need to see the property before quoting?','a':'Photos are a helpful starting point, but dimensions, levels, drainage and access all affect the proposed work. Arrange a free site visit so these details can be assessed.'}])}</div></section>'''


def about_details(image, button):
    return f'''<section class="section white content-band"><div class="wrap"><div class="section-heading" data-reveal><div><span class="eyebrow">From first conversation to finish</span><h2>The work starts<br>before the first block.</h2></div><p>A useful quote comes from understanding the property, the preparation and the result you want.</p></div><div class="approach-grid approach-grid--four"><article data-reveal><span class="process-number">01</span><h3>Walk through the space.</h3><p>At a site visit, we can look at where people walk, how vehicles enter, the levels around the house and where water currently goes. Show us what works and what you would like to change. Existing features you want to keep are part of that conversation too.</p></article><article data-reveal><span class="process-number">02</span><h3>Agree the whole job.</h3><p>Materials are only one part of the decision. Ground preparation, access, edges, steps, covers and boundaries can all influence the scope. Discuss the proposed finish alongside those practical details, then review the no-obligation quote before deciding.</p></article><article data-reveal><span class="process-number">03</span><h3>Look beyond the surface.</h3><p>Groundwork and the layers beneath the paving matter to the finished space. We consider the intended use and the condition of the existing area, along with the details where new work meets doors, walls, lawns and adjoining paths.</p></article><article data-reveal><span class="process-number">04</span><h3>Understand the finish.</h3><p>Different materials need different care. Discuss when a new surface can be used and ask about cleaning and looking after the paving, joints or timber chosen for your project. A practical layout should make everyday use and upkeep easier.</p></article></div></div></section><section class="section"><div class="wrap split">{image('charcoal-block-paved-driveway-house',cls='split-photo')}<div class="split-copy"><span class="eyebrow">See the work for yourself</span><h2>Real homes.<br>Individual details.</h2><p>Our gallery brings together driveways, patios, fencing and complete garden spaces. Look at the borders, curved entrances, steps and the way different surfaces connect, as well as the main paved area.</p><p>You might like the contrast of a dark driveway and a lighter border, or a paved seating area linked to the rest of the garden. Share the photographs that appeal to you. We can discuss the look you want and how it could suit the layout of your own property.</p>{button('Explore our work','/gallery/','outline')}</div></div></section>'''


def contact_steps(button):
    return f'''<section class="section white content-band contact-flow"><div class="wrap"><div class="section-heading" data-reveal><div><span class="eyebrow">What happens next</span><h2>A proper conversation.<br>A clearer plan.</h2></div><p>Whether you have a detailed idea or simply know what is not working, start by getting in touch.</p></div><div class="approach-grid"><article data-reveal><span class="process-number">01</span><h3>Share the starting point.</h3><p>Tell George where the property is and the type of work you are considering. Photographs of the whole area, the entrances and any problem sections help explain the job. Approximate dimensions are useful, but you do not need a finished design.</p></article><article data-reveal><span class="process-number">02</span><h3>Look at the property.</h3><p>A free site visit gives us a chance to discuss the layout, current ground and surface water, levels and access for materials. Point out any shared routes, gates, inspection covers or features that need to remain accessible.</p></article><article data-reveal><span class="process-number">03</span><h3>Agree what is included.</h3><p>Talk through material choices, borders, steps and any related landscaping or fencing. The quotation should reflect the work agreed for your space. You can ask questions about the scope and discuss arrangements before deciding whether to proceed.</p></article></div><div class="info-box"><h3>Planning more than one change?</h3><p>Mention the whole project when you get in touch. A driveway, path, patio and boundary may need to connect, and it is helpful to consider the sequence and finishing details together. If some elements are more important than others, let George know your priorities.</p><div class="actions">{button('Call George','tel:+447581223870')}{button('Compare our services','/services/','outline')}</div></div></div></section>'''


def area_details(button):
    return f'''<section class="section white content-band"><div class="wrap split"><div><span class="eyebrow">Before we visit</span><h2>The property matters<br>as much as the postcode.</h2><p class="muted">A narrow entrance, a sloping driveway or a garden reached through a side passage can all influence the work. Send a few photos of the access as well as the main area, and mention any shared routes or features you need to keep.</p><p class="muted">At the visit, we can discuss how you want to use the space, suitable materials and the connections to doors, paths, lawns and boundaries. The purpose is to agree a clear scope for your own property, rather than assume every driveway or garden needs the same solution.</p>{button('Ask about your address','/contact/')}</div><div class="service-aside"><span class="eyebrow">Available across our service area</span><h2>One local team.<br>A range of outdoor work.</h2><ul><li><a href="/services/driveways/">Tarmac, resin &amp; block paved driveways ↗</a></li><li><a href="/services/patios/">Indian stone &amp; porcelain patios ↗</a></li><li><a href="/services/landscaping/">Paths, lawns, planting &amp; edging ↗</a></li><li><a href="/services/fencing/">Timber fencing &amp; screening ↗</a></li></ul><p>Call or email with your location to check availability and arrange a free site visit.</p></div></div></section>'''


def review_followup(image, button):
    return f'''<section class="section white feedback-summary"><div class="wrap split">{image('grey-paved-patio-seating-area',cls='split-photo')}<div class="split-copy"><span class="eyebrow">From feedback to your own ideas</span><h2>Find the finish<br>you have in mind.</h2><p>Alongside these customer comments, our gallery gives you a closer look at the surfaces, borders and garden layouts we work on. Compare driveway patterns, patio shapes and the way steps and paths connect the space.</p><p>If something catches your eye, make a note of the photograph and share it with George. A site visit lets us discuss how the idea might fit your own property, with a free, no-obligation quote for the agreed work.</p><div class="actions">{button('Browse the gallery','/gallery/','outline')}{button('Discuss your project')}</div></div></div></section>'''
